        public static string GetStoreMappingSubfix(DateTime reportDate)
        {
            if (reportDate > BalanceUp.MoveBetsDay)
            {
                return string.Empty;
            }
            else if (reportDate >= BalanceUp.BalanceUpDay)
            {
                return BET_TRANS14_SP_SUFFIX;
            }
            else
            {
                return WARE_HOUSE_SP_SUFFIX;
            }
        }

        public static string GetSportName(object sportId)
        {
            switch (Convert.ToInt32(sportId))
            {
                case 0:
                    return ResourceExtension.GetResource(ResourceClass, "sportBook");
                case 161:
                    return ResourceExtension.GetResource(ResourceClass, "numbergame");
                case 162:
                    return ResourceExtension.GetResource(ResourceClass, "LiveCasino");
                case 180:
                    return ResourceExtension.GetResource(ResourceClass, "VirtualSports");
                case 251:
                    return ResourceExtension.GetResource(ResourceClass, "casino");
                case 151:
                    return ResourceExtension.GetResource(ResourceClass, "Racebook");
                case 252:
                    return ResourceExtension.GetResource(ResourceClass, "bingo");
                case 253:
                    return ResourceExtension.GetResource(ResourceClass, "P2P");
                case 202:
                    return ResourceExtension.GetResource(ResourceClass, "Keno");
                default:
                    return CacheRef.GetSportName(sportId);
            }
        }

        public static string GetLevelTitle(int roleId)
        {
            string result = "Unknown";

            switch (roleId)
            {
                case (int)(Sunplus.Agent.Model.BL.Definitions.UserTypes.Super):
                    result = ResourceExtension.GetResource(ResourceClass, "super");
                    break;

                case (int)(Sunplus.Agent.Model.BL.Definitions.UserTypes.Master):
                    result = ResourceExtension.GetResource(ResourceClass, "master");
                    break;

                case (int)(Sunplus.Agent.Model.BL.Definitions.UserTypes.Agent):
                    result = ResourceExtension.GetResource(ResourceClass, "agent");
                    break;

                case (int)(Sunplus.Agent.Model.BL.Definitions.UserTypes.Member):
                    result = ResourceExtension.GetResource(ResourceClass, "member");
                    break;

                default:
                    result = "Unknown";
                    break;
            }

            return result;
        }

        public static string FormatDateTime(string DateTimeString)
        {
            int year = Convert.ToInt32(DateTimeString.Substring(0, 4));
            int month = Convert.ToInt32(DateTimeString.Substring(4, 2));

            DateTime dt = new DateTime(year, month, 1);
            return dt.Month + "/" + dt.Year;
        }

        public static string FormatDateTimeforDaily(string DateTimeString)
        {
            int year = Convert.ToInt32(DateTimeString.Substring(0, 4));
            int month = Convert.ToInt32(DateTimeString.Substring(4, 2));
            int day = Convert.ToInt32(DateTimeString.Substring(6, 2));
            DateTime dt = new DateTime(year, month, day);
            return dt.Month + "/" + dt.Day + "/" + dt.Year;
        }
